<script module lang="ts">
/**
 * A vertical sequence of dated events (`design/components/timeline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/timeline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot, type IconRole } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/timeline.module.css'

export type TimelineTone = 'neutral' | 'accent' | 'info' | 'success' | 'warning' | 'danger'

export interface TimelineEvent {
  title: string
  time: string
  detail?: string
  icon?: IconRole
  tone?: TimelineTone
}

export interface TimelineProps {
  /**
   * Events in reading order; Timeline never sorts them.
   */
  events: TimelineEvent[]
  /**
   * The list's accessible name, such as "Ticket history" rather than "Timeline".
   */
  label: string
}
</script>

<script lang="ts">
let { events, label: labelOwn }: TimelineProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if events.length > 0
    }<ol class={styles.root} aria-label={label} data-member="timeline"
      >{#each events as event, at (at)
        }<li
          class={styles.event}
          data-tone={event.tone === undefined || event.tone === 'neutral' ? undefined : event.tone}
          ><span class={styles.marker} aria-hidden="true"
            ><span class={styles.mark} data-mark={event.icon === undefined ? 'dot' : 'icon'}
              >{#if event.icon !== undefined}<Icon name={event.icon} size="sm" />{/if
            }</span
          ></span
          ><span class={styles.copy}
            ><span class={styles.title}>{event.title}</span
            ><span class={styles.time}>{event.time}</span
            >{#if event.detail !== undefined}<span class={styles.detail}>{event.detail}</span>{/if
          }</span
        ></li
      >{/each
    }</ol
  >{/if
}{/if
}{@render joined.end?.()}
